    /// <summary>CMPSCR: $4999-$499E.</summary>
    private static ushort L4999_CMPSCR(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0x4999: // CMPSCR PSHS Y,X,D  (TB12REV3.ASM:1855)
                if (!g.I(0x4999, 11)) return 0x4999;
                g.PushS16(t.Y);
                g.PushS16(t.X);
                g.PushS(t.B);
                g.PushS(t.A);
                goto case 0x499B;
            case 0x499B: // EXG X,Y ;MAKE X POINT AT CMOS  (TB12REV3.ASM:1856)
                if (!g.I(0x499B, 8)) return 0x499B;
                { ushort a = g.Reg(0x1, 0x499D), b = g.Reg(0x2, 0x499D); g.SetReg(0x1, b); g.SetReg(0x2, a);
                }
                goto case 0x499D;
            case 0x499D: // LDB #4 ;4 BYTES THROUGH  (TB12REV3.ASM:1857)
                if (!g.I(0x499D, 2)) return 0x499D;
                t.B = 0x04; t.CC = Logic8(t.CC, t.B);
                return 0x499F;
        }
        return pc;
    }

    /// <summary>CMPSC1: $499F-$49A6.</summary>
    private static ushort L499F_CMPSC1(Gen g, ushort pc)
