    /// <summary>CMPSC2: $49A7-$49AF.</summary>
    private static ushort L49A7_CMPSC2(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0x49A7: // CMPSC2 CMPA ,Y+ ;COMPARE TO PLAYERS SCORE  (TB12REV3.ASM:1862)
                if (!g.I(0x49A7, 6)) return 0x49A7;
                ea = t.Y; t.Y += 1;
                Sub8(ref t.CC, t.A, g.Rd(ea));
                goto case 0x49A9;
            case 0x49A9: // BHI CMPSC4 ;CMOS SCORE HIGHER  (TB12REV3.ASM:1863)
                if (!g.I(0x49A9, 3)) return 0x49A9;
                if (Hi(t.CC)) return 0x49B0;
                goto case 0x49AB;
            case 0x49AB: // BLO CMPSC5 ;PLAYER'S SCORE HIGHER  (TB12REV3.ASM:1864)
                if (!g.I(0x49AB, 3)) return 0x49AB;
                if (Cs(t.CC)) return 0x49B4;
                goto case 0x49AD;
            case 0x49AD: // DECB ;SAME...ARE WE DONE??  (TB12REV3.ASM:1865)
                if (!g.I(0x49AD, 2)) return 0x49AD;
                t.B = Dec(ref t.CC, t.B);
                goto case 0x49AE;
            case 0x49AE: // BNE CMPSC1 ;NOPE...COMPARE ANOTHER BYTE  (TB12REV3.ASM:1866)
                if (!g.I(0x49AE, 3)) return 0x49AE;
                if (!Eq(t.CC)) return 0x499F;
                return 0x49B0;
        }
        return pc;
    }

